import styles from './MacroRing.module.css'

const RADIUS = 36
const CIRC = 2 * Math.PI * RADIUS

const MACRO_CONFIG = {
  protein: { color: '#f4b8c8', dark: '#c97a90', label: 'Protein' },
  carbs:   { color: '#c8b8f0', dark: '#9a7ad4', label: 'Carbs' },
  fat:     { color: '#f8c8a8', dark: '#c07040', label: 'Fat' },
}

export default function MacroRing({ macro, value, goal, unit = 'g' }) {
  const cfg = MACRO_CONFIG[macro]
  const pct = Math.min(1, goal > 0 ? value / goal : 0)
  const dashOffset = CIRC * (1 - pct)

  return (
    <div className={styles.wrap}>
      <svg width="88" height="88" viewBox="0 0 88 88" className={styles.svg}>
        <circle cx="44" cy="44" r={RADIUS} stroke="#f0e8ea" strokeWidth="7" fill="none" />
        <circle
          cx="44" cy="44" r={RADIUS}
          stroke={cfg.dark}
          strokeWidth="7"
          fill="none"
          strokeDasharray={CIRC}
          strokeDashoffset={dashOffset}
          strokeLinecap="round"
          transform="rotate(-90 44 44)"
          style={{ transition: 'stroke-dashoffset 0.6s ease' }}
        />
        <text x="44" y="44" textAnchor="middle" dominantBaseline="middle"
          fontSize="13" fontStyle="italic" fill={cfg.dark} fontFamily="Playfair Display, Georgia, serif" fontWeight="600">
          {Math.round(pct * 100)}%
        </text>
      </svg>
      <div className={styles.label} style={{ color: cfg.dark }}>{cfg.label}</div>
      <div className={styles.value}>{value}<span className={styles.unit}>{unit}</span></div>
    </div>
  )
}

