import Anthropic from '@anthropic-ai/sdk'
import { useUser } from '../context/UserContext'
import { scoreMeal } from '../utils/scoreMeal'
import { isVegKeyword } from '../utils/filterByPreference'
import ScoreBadge from '../components/ScoreBadge'
import BottomNav from '../components/BottomNav'
import styles from './Scan.module.css'

const client = new Anthropic({
  apiKey: import.meta.env.VITE_ANTHROPIC_API_KEY,
  dangerouslyAllowBrowser: true,
})

const MEAL_TIMES = ['breakfast', 'lunch', 'dinner', 'snack']
const MOODS = ['😊 Great', '😐 Okay', '😴 Tired', '💪 Energized', '😩 Sluggish']

export default function Scan() {
  const { dietaryPreference, addDiaryEntry } = useUser()
  const [image, setImage] = useState(null)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState(null)
  const [error, setError] = useState(null)
  const [mealTime, setMealTime] = useState(guessCurrentMeal())
  const [mood, setMood] = useState('')
  const [added, setAdded] = useState(false)
  const fileRef = useRef()
  const cameraRef = useRef()

  function guessCurrentMeal() {
    const h = new Date().getHours()
    if (h < 10) return 'breakfast'
    if (h < 14) return 'lunch'
    if (h < 18) return 'snack'
    return 'dinner'
  }

  function handleFile(e) {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = ev => {
      setImage(ev.target.result)
      setResult(null)
      setError(null)
      setAdded(false)
      analyzeImage(ev.target.result)
    }
    reader.readAsDataURL(file)
  }

  async function analyzeImage(dataUrl) {
    setLoading(true)
    setError(null)
    try {
      if (!import.meta.env.VITE_ANTHROPIC_API_KEY) {
        setResult(getMockResult())
        setLoading(false)
        return
      }

      const base64 = dataUrl.split(',')[1]
      const mediaType = dataUrl.split(';')[0].split(':')[1]

      const msg = await client.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 600,
        messages: [{
          role: 'user',
          content: [
            {
              type: 'image',
              source: { type: 'base64', media_type: mediaType, data: base64 }
            },
            {
              type: 'text',
              text: `Analyze this food image. Respond ONLY with a JSON object, no markdown:
{
  "name": "food name",
  "kcal": number,
  "protein": number (grams),
  "carbs": number (grams),
  "fat": number (grams),
  "confidence": number (0-100),
  "isVeg": boolean,
  "alternative": "healthier ${dietaryPreference === 'veg' ? 'vegetarian ' : ''}alternative suggestion"
}
Estimate for a standard serving. If multiple items, sum them up.`
            }
          ]
        }]
      })

      const text = msg.content[0].text.trim()
      const json = JSON.parse(text)
      const score = scoreMeal(json)
      setResult({ ...json, score })
    } catch (e) {
      setError('Could not analyze the image. Please try again.')
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  function getMockResult() {
    return {
      name: 'Mixed grain bowl', kcal: 420, protein: 18, carbs: 55, fat: 12,
      confidence: 87, isVeg: true, score: 8,
      alternative: dietaryPreference === 'veg'
        ? 'Try adding edamame for more protein'
        : 'Add grilled chicken for extra protein'
    }
  }

  function addToDiary() {
    if (!result) return
    addDiaryEntry({
      name: result.name,
      kcal: result.kcal,
      protein: result.protein,
      carbs: result.carbs,
      fat: result.fat,
      score: result.score,
      isVeg: result.isVeg ?? isVegKeyword(result.name),
      mealTime,
      mood: mood.split(' ')[1] || '',
    })
    setAdded(true)
  }

  return (
    <div className={`page ${styles.scan}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Snap a meal</h1>
        <p className={styles.sub}>Point at food to get instant nutrition</p>
      </div>

      {/* Viewfinder */}
      <div className={styles.viewfinder} onClick={() => !image && fileRef.current.click()}>
        {image ? (
          <img src={image} alt="food" className={styles.preview} />
        ) : (
          <div className={styles.placeholder}>
            <div className={styles.corner} />
            <CameraIcon />
            <p className={styles.placeholderText}>Tap to take / upload a photo</p>
          </div>
        )}
        {loading && (
          <motion.div className={styles.loader}
            animate={{ opacity: [0.5, 1, 0.5] }}
            transition={{ duration: 1.2, repeat: Infinity }}>
            <div className={styles.pulse} />
            <span>Analyzing with AI...</span>
          </motion.div>
        )}
      </div>

      <div className={styles.actions}>
        <button className={styles.uploadBtn} onClick={() => fileRef.current.click()}>
          Upload photo
        </button>
        <button className={styles.cameraBtn} onClick={() => cameraRef.current.click()}>
          Camera
        </button>
      </div>

      <input ref={fileRef} type="file" accept="image/*" hidden onChange={handleFile} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" hidden onChange={handleFile} />

      {error && <p className={styles.error}>{error}</p>}

      {/* Result card */}
      <AnimatePresence>
        {result && !loading && (
          <motion.div className={styles.result}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.4 }}>

            <div className={styles.resultHeader}>
              <span className={styles.vegDot} style={{ background: result.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }} />
              <h2 className={styles.foodName}>{result.name}</h2>
              <ScoreBadge score={result.score} />
            </div>

            <div className={styles.macroRow}>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-dark)' }}>
                <span className={styles.macroVal}>{result.kcal}</span>
                <span className={styles.macroLbl}>kcal</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-dark)' }}>
                <span className={styles.macroVal}>{result.protein}g</span>
                <span className={styles.macroLbl}>protein</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-lavender)', color: 'var(--lavender-dark)' }}>
                <span className={styles.macroVal}>{result.carbs}g</span>
                <span className={styles.macroLbl}>carbs</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-peach)', color: 'var(--peach-dark)' }}>
                <span className={styles.macroVal}>{result.fat}g</span>
                <span className={styles.macroLbl}>fat</span>
              </div>
            </div>

            <div className={styles.confidence}>
              Confidence: <strong>{result.confidence}%</strong>
            </div>

            {result.alternative && (
              <div className={styles.altCard}>
                <span className={styles.altLabel}>Healthier alternative</span>
                <p className={styles.altText}>{result.alternative}</p>
              </div>
            )}

            {/* Meal time selector */}
            <div className={styles.timeRow}>
              {MEAL_TIMES.map(t => (
                <button
                  key={t}
                  className={`${styles.timeChip} ${mealTime === t ? styles.timeActive : ''}`}
                  onClick={() => setMealTime(t)}>
                  {t}
                </button>
              ))}
            </div>

            {/* Mood tag */}
            <div className={styles.moodRow}>
              <span className={styles.moodLabel}>How do you feel?</span>
              <div className={styles.moodChips}>
                {MOODS.map(m => (
                  <button
                    key={m}
                    className={`${styles.moodChip} ${mood === m ? styles.moodActive : ''}`}
                    onClick={() => setMood(m === mood ? '' : m)}>
                    {m}
                  </button>
                ))}
              </div>
            </div>

            {added ? (
              <div className={styles.addedMsg}>Added to diary ✓</div>
            ) : (
              <button className={styles.addBtn} onClick={addToDiary}>
                Add to Diary
              </button>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  )
}

function CameraIcon() {
  return (
    <svg width="48" height="48" viewBox="0 0 24 24" fill="none" opacity="0.4">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" stroke="#c97a90" strokeWidth="1.5" fill="none" strokeLinejoin="round" />
      <circle cx="12" cy="13" r="4" stroke="#c97a90" strokeWidth="1.5" />
    </svg>
  )
}

