.prefNote { font-size: 12px; color: var(--text-muted); margin-top: 10px; }
.settingRow { display: flex; align-items: center; justify-content: space-between; }
.settingLabel { font-size: 14px; color: var(--text); }
.toggle {
  width: 44px; height: 24px;
  border-radius: 12px;
  background: #e8e0e8;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
}
.toggleOn { background: var(--rose); }
.toggleThumb {
  position: absolute;
  top: 2px; left: 2px;
  width: 20px; height: 20px;
  border-radius: 50%;
